<script setup lang="ts">
import{computed,ref}from 'vue';import{useQuery,useQueryClient}from '@tanstack/vue-query';import{api}from '@/api/client';type Notice={id:number;title:string;message:string;read_at?:string};const c=useQueryClient();const email=ref(true);const sms=ref(false);const push=ref(false);const msg=ref('');const err=ref('');const q=useQuery({queryKey:['notifications'],queryFn:async()=>{const r=await api.get('/notifications');return r.data.data??[]}});const list=computed<Notice[]>(()=>q.data.value??[]);async function refresh(){await c.invalidateQueries({queryKey:['notifications']})}async function read(n:Notice){try{await api.post(`/notifications/${n.id}/read`);await refresh()}catch(e:any){err.value=e.response?.data?.message??'Could not update notification.'}}async function readAll(){try{await api.post('/notifications/read-all');await refresh()}catch(e:any){err.value=e.response?.data?.message??'Could not update notifications.'}}async function prefs(){try{await api.put('/notification-preferences',{email_enabled:email.value,sms_enabled:sms.value,push_enabled:push.value});msg.value='Preferences saved.'}catch(e:any){err.value=e.response?.data?.message??'Preferences could not be saved.'}}</script>
<template><header class="page-header"><div><p class="eyebrow">INBOX</p><h1>Notifications</h1><p class="muted">Read operational updates and set delivery preferences.</p></div><button class="secondary-button" @click="readAll">Mark all read</button></header><p v-if="msg" class="action-message success">{{msg}}</p><p v-if="err" class="action-message error">{{err}}</p><section class="membership-top-grid"><article class="panel"><h2>Inbox</h2><div class="notice-list"><button v-for="n in list" :key="n.id" :class="{unread:!n.read_at}" @click="read(n)"><strong>{{n.title}}</strong><span>{{n.message}}</span><small>{{n.read_at?'Read':'New'}}</small></button><p v-if="!list.length" class="muted">No notifications.</p></div></article><article class="panel membership-form"><h2>Preferences</h2><form @submit.prevent="prefs"><label class="checkbox-label"><input v-model="email" type="checkbox"/> Email</label><label class="checkbox-label"><input v-model="sms" type="checkbox"/> SMS</label><label class="checkbox-label"><input v-model="push" type="checkbox"/> Push</label><button class="primary-button">Save preferences</button></form></article></section></template>
